import Model from 'flarum/common/Model';
export default class Campaign extends Model {
  name = (() => Model.attribute('name'))();
  status = (() => Model.attribute('status'))();
  tier = (() => Model.attribute('tier'))();
  isHouse = (() => Model.attribute('isHouse'))();
  startsAt = (() => Model.attribute('startsAt', Model.transformDate))();
  endsAt = (() => Model.attribute('endsAt', Model.transformDate))();
  maxImpressions = (() => Model.attribute('maxImpressions'))();
  maxClicks = (() => Model.attribute('maxClicks'))();
  pacing = (() => Model.attribute('pacing'))();
  frequencyCap = (() => Model.attribute('frequencyCap'))();
  frequencyWindow = (() => Model.attribute('frequencyWindow'))();

  /** 42 hex characters: 168 bits, one per hour of the week. Null means always. */
  daypartMask = (() => Model.attribute('daypartMask'))();
  rateType = (() => Model.attribute('rateType'))();
  rateAmount = (() => Model.attribute('rateAmount'))();
  rateCurrency = (() => Model.attribute('rateCurrency'))();
  contractNotes = (() => Model.attribute('contractNotes'))();
  impressions = (() => Model.attribute('impressions'))();
  clicks = (() => Model.attribute('clicks'))();

  /**
   * Computed on the server from the dates and the caps, so it disagrees with
   * `status` whenever an administrator's intent and reality have parted ways —
   * which is the moment worth showing them.
   */
  isLive = (() => Model.attribute('isLive'))();
  createdAt = (() => Model.attribute('createdAt', Model.transformDate))();
  rules = (() => Model.attribute('rules'))();
  advertiser = (() => Model.hasOne('advertiser'))();
  creatives = (() => Model.hasMany('creatives'))();
}
flarum.reg.add('datlechin-placements', 'admin/models/Campaign', Campaign);